motMachine valeurDépilerJava(motMachine *stockagePile,int *valeurProfondeur){if(*valeurProfondeur<=0||*valeurProfondeur>128)testÉchecJava();return stockagePile[--*valeurProfondeur];}
motMachine tableauJava(int nombreÉlémentsÉlémentListe){if(nombreÉlémentsÉlémentListe<0||(unsigned)nombreÉlémentsÉlémentListe+1>8192-capacitéUtilisé)testÉchecJava();motMachine*positionDonnées=stockageTas+capacitéUtilisé;capacitéUtilisé+=nombreÉlémentsÉlémentListe+1;positionDonnées[0]=nombreÉlémentsÉlémentListe;return (motMachine)positionDonnées;}
