int divisionJava(int coordonnéeCoordonnéeHorizontale,int coordonnéeCoordonnéeVerticale,int valeurResteDivision){if(!coordonnéeCoordonnéeVerticale)testÉchecJava();if(coordonnéeCoordonnéeHorizontale==(-2147483647-1)&&coordonnéeCoordonnéeVerticale==-1)return valeurResteDivision?0:coordonnéeCoordonnéeHorizontale;return valeurResteDivision?coordonnéeCoordonnéeHorizontale%coordonnéeCoordonnéeVerticale:coordonnéeCoordonnéeHorizontale/coordonnéeCoordonnéeVerticale;}
static unsigned longueur(const char*donnéesChaîne){unsigned nombreÉlémentsÉlémentListe=0;if(!donnéesChaîne)testÉchecJava();while(donnéesChaîne[nombreÉlémentsÉlémentListe])nombreÉlémentsÉlémentListe++;return nombreÉlémentsÉlémentListe;}
