    if(valeurNumérique){char valeurDeuxième[16];unsigned nombreÉlémentsÉlémentListe=0;int valeur=(int)positionDonnées;unsigned valeurNonSigné=valeur<0?0-(unsigned)valeur:valeur;do{valeurDeuxième[nombreÉlémentsÉlémentListe++]='0'+valeurNonSigné%10;valeurNonSigné/=10;}while(valeurNonSigné);if(valeur<0)valeurDeuxième[nombreÉlémentsÉlémentListe++]='-';while(nombreÉlémentsÉlémentListe)écrireDonnéesFichier(1,valeurDeuxième+--nombreÉlémentsÉlémentListe,1);}
