motMachine écritureFichierJava(motMachine chemin,motMachine valeur){const char*donnéesChaîne=(const char*)valeur;unsigned nombreÉlémentsÉlémentListe=longueur(donnéesChaîne);int poignéeFichier=ouvrirFichier((const char*)chemin,écrireValeurSeulement|ManquantSiCréer|ContenuTronquer,0600);if(poignéeFichier<0)testÉchecJava();int valeurRetourné=écrireDonnéesFichier(poignéeFichier,donnéesChaîne,nombreÉlémentsÉlémentListe);fermerFichier(poignéeFichier);if(valeurRetourné!=(int)nombreÉlémentsÉlémentListe)testÉchecJava();return 0;}
motMachine lectureFichierJava(motMachine chemin){int poignéeFichier=ouvrirFichier((const char*)chemin,lireValeurSeulement,0);if(poignéeFichier<0)testÉchecJava();int nombreÉlémentsÉlémentListe=tailleFichier(poignéeFichier);if(nombreÉlémentsÉlémentListe<0||nombreÉlémentsÉlémentListe>16384||(unsigned)(nombreÉlémentsÉlémentListe+8)/8>8192-capacitéUtilisé)testÉchecJava();char*positionDonnées=(char*)(stockageTas+capacitéUtilisé);capacitéUtilisé+=(nombreÉlémentsÉlémentListe+8)/8;int valeurRetourné=lireDonnéesFichier(poignéeFichier,positionDonnées,nombreÉlémentsÉlémentListe);fermerFichier(poignéeFichier);if(valeurRetourné!=nombreÉlémentsÉlémentListe)testÉchecJava();positionDonnées[nombreÉlémentsÉlémentListe]=0;return (motMachine)positionDonnées;}
